from pathlib import Path
import numpy as np
p=argparse.ArgumentParser();p.add_argument('--capture',type=Path,required=True);p.add_argument('--certificate',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();cap=a.capture.resolve();cert=a.certificate.resolve();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);m=json.loads((cap/'manifest.json').read_text());cm=json.loads((cert/'manifest.json').read_text());q=np.genfromtxt(cert/'n10.csv.gz',delimiter=',',names=True);old=np.genfromtxt(cap/'n10/poles.csv.gz',delimiter=',',names=True);assert len(q)==600 and len(old)==600;common=list(old.dtype.names);bitwise={f:q[f].tobytes()==old[f].tobytes() for f in common};assert all(bitwise.values());result=cm['results']['n10'];method=result['methods'][0];r=q[q['row']==method['row']][0];fields=['chi','Khat','Theta','alpha','Axx','Axy','Axz','Ayy','Ayz','Azz','LambdaX','LambdaY','LambdaZ'];maxima={}
